using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient via MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define tools ---
var tools = new List<AITool>
{
    AIFunctionFactory.Create(SearchWeb),
    AIFunctionFactory.Create(TakeNote),
    AIFunctionFactory.Create(GetNotes),
};

// --- Create the research agent using Microsoft Agent Framework ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Given a topic, you:
        1. Search the web for relevant information (perform multiple searches if needed).
        2. Take notes on key findings using the note-taking tool.
        3. After gathering enough information, retrieve your notes and produce a concise summary.

        Always search at least twice with different queries to get a broad perspective.
        Always take notes before summarizing. Use markdown formatting in the summary.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// --- Run the agent ---
var topic = args.Length > 0
    ? string.Join(' ', args)
    : "recent advances in quantum computing 2025";

Console.WriteLine($"🔍 Researching: {topic}\n");

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}");

Console.WriteLine("📋 Research Summary:\n");
Console.WriteLine(response.Text);

// --- Tool implementations ---

[Description("Searches the web for information on a given query. Returns search result snippets.")]
static string SearchWeb(
    [Description("The search query string")] string query)
{
    // Simulated web search results for demonstration purposes.
    // In production, replace with a real search API (e.g., Bing Search API).
    Console.WriteLine($"  🌐 Searching: \"{query}\"");

    return $$"""
        Search results for "{{query}}":

        1. [Research Article] - Key findings related to {{query}} show significant progress
           in the field. Recent studies demonstrate breakthroughs in efficiency and scalability.
           Published 2025.

        2. [News Report] - Industry experts predict major developments in {{query}}.
           Multiple companies are investing heavily in this area with promising early results.

        3. [Academic Paper] - A comprehensive review of {{query}} reveals emerging trends
           including improved methodologies and novel applications across multiple domains.
        """;
}

[Description("Takes a note to remember a key finding during research.")]
static string TakeNote(
    [Description("The title or category for this note")] string title,
    [Description("The content of the note")] string content)
{
    Console.WriteLine($"  📝 Note taken: {title}");
    Notes.Add((title, content));
    return $"Note saved: \"{title}\"";
}

[Description("Retrieves all notes taken during research.")]
static string GetNotes()
{
    if (Notes.Count == 0)
        return "No notes have been taken yet.";

    var result = "All research notes:\n\n";
    for (int i = 0; i < Notes.Count; i++)
    {
        result += $"## {i + 1}. {Notes[i].Title}\n{Notes[i].Content}\n\n";
    }
    return result;
}

/// <summary>In-memory store for notes collected during research.</summary>
static partial class Notes
{
    private static readonly List<(string Title, string Content)> _notes = [];
    public static void Add((string Title, string Content) note) => _notes.Add(note);
    public static int Count => _notes.Count;
    public static (string Title, string Content) this[int index] => _notes[index];
}

